/*
 * A083362  Square table, read by antidiagonals, of least distinct positive
 *          integers such that the sum of any two consecutive terms in any row
 *          is a square number.
 * https://oeis.org/A083362
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabl, nice
 * Formula:   a(n) = T(i,j) where (i,j) = antidiagonal_coords(n) T(0,k) =
 *            (k+1)*(k+2)/2 (k>=0) T(n,0) = floor((n+1)^2/2) (n>0) T(n,k+1) =
 *            (2*floor((n+1)/2) + k+1)^2 - T(n,k) (n>0,k>=0) i.e., each row is
 *            generated by that recurrence
 * Range:     u8 n <= 71, u16 n <= 71, u32 n <= 71, u64 n <= 71, u128 n <= 71,
 *            big any n
 * Helpers:   antidiagonal_coords
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include "../utils/antidiagonal_coords.h"

seq_t a(idx_t n)
{
    idx_t i, j;
    antidiagonal_coords(n, &i, &j);

    /* row 0 */
    if (i == 0) {
        seq_t kk = (seq_t)(j + 1);
        return (kk * (kk + 1)) / 2;
    }

    /* first column (except the first element) */
    if (j == 0) {
        seq_t ii = (seq_t)(i + 1);
        return (ii * ii) / 2;
    }

    /* general case: generate the row by recurrence up to column j */
    seq_t ii = (seq_t)(i + 1);
    seq_t val = ii * ii / 2;     /* T(i,0) */
    seq_t m   = ii / 2;          /* floor((i+1)/2) */

    for (idx_t k = 0; k < j; ++k) {
        seq_t base = 2 * m + ((seq_t)k + 1);
        val = base * base - val; /* T(i,k+1) from T(i,k) */
    }
    return val;
}
